  font-family: 'Barlow Condensed', sans-serif;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  text-decoration: none;
  color: rgba(255,255,255,0.7);
  padding: 8px 14px;
  border-radius: var(--radius);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.nav-link:hover, .nav-link.active {
  color: #fff;
  background: rgba(255,255,255,0.06);
}
.nav-link.active { color: var(--red); }
.nav-ctas {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}
.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  cursor: pointer;
  padding: 8px;
  margin-left: auto;
  border-radius: var(--radius);
}
.nav-toggle:focus-visible { outline: 2px solid var(--red); }

/* ── Page Hero (inner pages) ── */
.page-hero {
  padding: calc(var(--nav-h) + 60px) 48px 80px;
  background: linear-gradient(160deg, #0a0a0a 0%, #1a0000 60%, #0a0a0a 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(255,0,0,0.12) 0%, transparent 60%);
  pointer-events: none;
}
.page-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 800px;
}
.page-hero-tag {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 20px;
  display: block;
}
.page-hero h1 {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: clamp(52px, 8vw, 96px);
  font-weight: 900;
  text-transform: uppercase;
  line-height: 0.92;
  color: #fff;
  letter-spacing: -1px;
}

/* ── Footer ── */
.site-footer {
  background: #0a0a0a;
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 80px 48px 0;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 80px;
  padding-bottom: 64px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.footer-tagline {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 1px;
  color: rgba(255,255,255,0.4);
  text-transform: uppercase;
  margin-top: 12px;
  margin-bottom: 24px;
}
.country-select {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius);
  color: rgba(255,255,255,0.65);
  font-family: 'Barlow', sans-serif;
  font-size: 14px;
  padding: 10px 16px;
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition-fast);
}
.country-select:focus { border-color: var(--red); }
.footer-cols {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}
.footer-col-title {
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 20px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }
.footer-col a {
  font-family: 'Barlow', sans-serif;
  font-size: 14px;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: color var(--transition-fast);
}
.footer-col a:hover { color: var(--red); }
.footer-col a:focus-visible { outline: 2px solid var(--red); border-radius: 2px; }
.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 0;
  font-family: 'Barlow', sans-serif;
  font-size: 13px;
  color: rgba(255,255,255,0.25);
}

/* ── Divider ── */
.red-rule {
  width: 48px;
  height: 3px;
  background: var(--red);
  margin-bottom: 24px;
}

/* ── Scroll margin ── */
[id] { scroll-margin-top: calc(var(--nav-h) + 16px); }

/* ── Responsive Nav ── */
@media (max-width: 1024px) {
  .nav-inner { gap: 20px; }
  .nav-link { padding: 8px 10px; font-size: 12px; }
}

@media (max-width: 768px) {
  .nav-toggle { display: flex; }
  .nav-links {
    display: none;
    flex-direction: column;
    position: absolute;
    top: var(--nav-h);
    left: 0; right: 0;
    background: #0a0a0a;
    border-bottom: 1px solid rgba(255,0,0,0.15);
    padding: 20px 24px;
    gap: 4px;
  }
  .nav-links.open { display: flex; }
  .nav-ctas { display: none; }
  .nav-inner { flex-wrap: wrap; }
  .page-hero { padding: calc(var(--nav-h) + 40px) 24px 60px; }
  .site-footer { padding: 60px 24px 0; }
  .footer-inner { grid-template-columns: 1fr; gap: 48px; }
  .footer-cols { grid-template-columns: repeat(2, 1fr); }
  .section-label { font-size: 11px; }
}

@media (max-width: 480px) {
  .footer-cols { grid-template-columns: 1fr; }
  .btn-xl { padding: 18px 36px; font-size: 15px; }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

