    // ── Floor/Treadmill Toggle ──
    (function() {
      const btnFloor = document.getElementById('btnFloor');
      const btnTreadmill = document.getElementById('btnTreadmill');
      const panelFloor = document.getElementById('panelFloor');
      const panelTreadmill = document.getElementById('panelTreadmill');

      function activate(which) {
        const isFloor = which === 'floor';
        btnFloor.setAttribute('aria-pressed', isFloor ? 'true' : 'false');
        btnTreadmill.setAttribute('aria-pressed', isFloor ? 'false' : 'true');
        panelFloor.classList.toggle('active', isFloor);
        panelTreadmill.classList.toggle('active', !isFloor);
      }

      btnFloor.addEventListener('click', () => activate('floor'));
      btnTreadmill.addEventListener('click', () => activate('treadmill'));
    })();

    // ── Newsletter ──
    (function() {
      const form = document.getElementById('newsletterFormW');
      const input = document.getElementById('nlEmailW');
      const errorEl = document.getElementById('nl-error-w');
      const successEl = document.getElementById('nl-success-w');
      const emailRx = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        const val = input.value.trim();
        errorEl.style.display = 'none';
        successEl.style.display = 'none';
        input.classList.remove('error');
        if (!val || !emailRx.test(val)) {
          input.classList.add('error');
          errorEl.textContent = val ? 'Please enter a valid email address.' : 'Please enter your email address.';
          errorEl.style.display = 'block';
          input.focus();
          return;
        }
        form.reset();
        successEl.textContent = "You're in! Check your inbox for a welcome from RedRoom.";
        successEl.style.display = 'block';
      });
    })();
