  <script>
    // ── Instructor Filter ──
    (function() {
      const pills = document.querySelectorAll('.filter-pill');
      const cards = document.querySelectorAll('.instructor-card');
      const resultsEl = document.getElementById('filterResults');
      const emptyEl = document.getElementById('gridEmpty');

      function applyFilter(filter) {
        let visible = 0;
        cards.forEach(function(card) {
          const loc = card.getAttribute('data-location');
          const show = filter === 'all' || loc === filter;
          card.classList.toggle('hidden', !show);
          if (show) visible++;
        });

        // Update results count
        const locLabel = filter === 'all' ? 'all locations' : filter;
        resultsEl.textContent = `Showing ${visible} instructor${visible !== 1 ? 's' : ''} ${filter === 'all' ? '' : 'in ' + locLabel}`;

        // Empty state
        emptyEl.classList.toggle('visible', visible === 0);
      }

      pills.forEach(function(pill) {
        pill.addEventListener('click', function() {
          pills.forEach(function(p) {
            p.classList.remove('active');
            p.setAttribute('aria-pressed', 'false');
          });
          pill.classList.add('active');
          pill.setAttribute('aria-pressed', 'true');
          applyFilter(pill.getAttribute('data-filter'));
        });
      });
    })();

    // ── Newsletter ──
    (function() {
      const form = document.getElementById('newsletterFormI');
      const input = document.getElementById('nlEmailI');
      const errorEl = document.getElementById('nl-error-i');
      const successEl = document.getElementById('nl-success-i');
      const emailRx = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        const val = input.value.trim();
        errorEl.style.display = 'none';
        successEl.style.display = 'none';
        input.classList.remove('error');
        if (!val || !emailRx.test(val)) {
          input.classList.add('error');
          errorEl.textContent = val ? 'Please enter a valid email address.' : 'Please enter your email address.';
          errorEl.style.display = 'block';
          input.focus();
          return;
        }
        form.reset();
        successEl.textContent = "You're in! Check your inbox for a welcome from RedRoom.";
        successEl.style.display = 'block';
      });
    })();
  </script>
