    // ── FAQ Accordion (single-open) ──
    (function() {
      const items = document.querySelectorAll('.faq-item');

      items.forEach(function(item) {
        const btn = item.querySelector('.faq-question');
        const wrapper = item.querySelector('.faq-answer-wrapper');

        btn.addEventListener('click', function() {
          const isOpen = item.classList.contains('open');

          // Close all
          items.forEach(function(i) {
            i.classList.remove('open');
            i.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
            i.querySelector('.faq-answer-wrapper').classList.remove('open');
          });

          // Open clicked if it was closed
          if (!isOpen) {
            item.classList.add('open');
            btn.setAttribute('aria-expanded', 'true');
            wrapper.classList.add('open');
          }
        });
      });
    })();

    // ── Newsletter ──
    (function() {
      const form = document.getElementById('newsletterFormR');
      const input = document.getElementById('nlEmailR');
      const errorEl = document.getElementById('nl-error-r');
      const successEl = document.getElementById('nl-success-r');
      const emailRx = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        const val = input.value.trim();
        errorEl.style.display = 'none';
        successEl.style.display = 'none';
        input.classList.remove('error');
        if (!val || !emailRx.test(val)) {
          input.classList.add('error');
          errorEl.textContent = val ? 'Please enter a valid email address.' : 'Please enter your email address.';
          errorEl.style.display = 'block';
          input.focus();
          return;
        }
        form.reset();
        successEl.textContent = "You're in! Check your inbox for a welcome from RedRoom.";
        successEl.style.display = 'block';
      });
    })();
